"""Station registry.

Two sources (both KAUR, official):

* ``config/stations.toml`` -- verified stations. Generated by ``pvt sync-stations`` from the
  climate dataset API table ``f_kliima_jaam_vaatlus`` (station code, current-period
  coordinates and height), which is also the T2 truth source. Verified = coordinates and
  height come from that table.
* ``<data_root>/meta/xml_met_stations.parquet`` -- all stations seen in the observations XML
  (name, WMO code, coordinates). Written by ``pvt ingest-obs-xml``. These have no height
  source and are therefore ``verified = false`` (excluded from scores, docs/08), but ECMWF
  values are still archived at their location.
"""

from __future__ import annotations

import logging
import math
import unicodedata
from dataclasses import dataclass
from pathlib import Path
from typing import Any

import polars as pl
import requests

from pvt.config import Settings, Station
from pvt.timeutil import format_utc, utc_now

LOG = logging.getLogger(__name__)

KLIIMA_STATION_TABLE = "f_kliima_jaam_vaatlus"
OPEN_END = "3999-12-31"
MATCH_RADIUS_KM = 1.0

STATION_TARGETS_SCHEMA: dict[str, pl.DataType] = {
    "station_id": pl.String(),
    "name": pl.String(),
    "lat_deg": pl.Float64(),
    "lon_deg": pl.Float64(),
    "height_m_EH2000": pl.Float64(),
    "verified": pl.Boolean(),
    "source": pl.String(),
}


def haversine_km(lat1: float, lon1: float, lat2: float, lon2: float) -> float:
    """Great-circle distance in km (spherical Earth, R = 6371.0 km)."""
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dphi = p2 - p1
    dlmb = math.radians(lon2 - lon1)
    a = math.sin(dphi / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dlmb / 2) ** 2
    return 2 * 6371.0 * math.asin(math.sqrt(a))


def slug(name: str) -> str:
    """ASCII station id fragment, e.g. ``"Kuressaare linn"`` -> ``"KURESSAARE_LINN"``."""
    ascii_name = unicodedata.normalize("NFKD", name).encode("ascii", "ignore").decode()
    return "".join(c if c.isalnum() else "_" for c in ascii_name.upper()).strip("_")


@dataclass(frozen=True)
class KliimaStation:
    """Current-period metadata of one climate station."""

    station_id: str
    name: str
    lat_deg: float
    lon_deg: float
    height_m: float
    period_start: str


def fetch_kliima_stations(base_url: str, timeout_s: int = 60) -> list[KliimaStation]:
    """Read current-period station metadata from the climate API (PostgREST).

    Rows whose ``jaam_periood_lopp`` is the open end (3999-12-31) describe the current
    location; earlier periods (relocations) are ignored.
    """
    url = f"{base_url.rstrip('/')}/{KLIIMA_STATION_TABLE}"
    params = {
        "select": "jaam_kood,jaam_nimi,laiuskraad,pikkuskraad,korgus_merepinnast_m,"
        "jaam_periood_algus,jaam_periood_lopp",
        "jaam_periood_lopp": f"gte.{OPEN_END}",
        "limit": "20000",
    }
    r = requests.get(url, params=params, timeout=timeout_s)
    r.raise_for_status()
    rows: list[dict[str, Any]] = r.json()
    by_id: dict[str, KliimaStation] = {}
    for row in rows:
        st = KliimaStation(
            station_id=row["jaam_kood"],
            name=row["jaam_nimi"],
            lat_deg=float(row["laiuskraad"]),
            lon_deg=float(row["pikkuskraad"]),
            height_m=float(row["korgus_merepinnast_m"]),
            period_start=str(row["jaam_periood_algus"]),
        )
        prev = by_id.get(st.station_id)
        if prev is not None and prev != st:
            raise ValueError(f"conflicting current metadata for {st.station_id}")
        by_id[st.station_id] = st
    return [by_id[k] for k in sorted(by_id)]


def render_stations_toml(
    stations: list[KliimaStation], existing: dict[str, Station], base_url: str
) -> str:
    """Render config/stations.toml; WMO codes of existing entries are preserved."""
    src = f"{base_url.rstrip('/')}/{KLIIMA_STATION_TABLE}"
    lines = [
        "# Station register -- GENERATED by `pvt sync-stations`; edit wmo_code only.",
        "#",
        f"# Coordinates (EPSG:4326) and heights: KAUR climate dataset API, table {src}",
        "# (columns laiuskraad, pikkuskraad, korgus_merepinnast_m; current station period,",
        "# jaam_periood_lopp = 3999-12-31). The API describes the height as 'Height of station",
        "# ground above mean sea level (Amsterdam)'; EH2000 is the Amsterdam-referenced Estonian",
        "# system -- confirm with KAUR that the column is EH2000 (reports/stage_1b.md).",
        "# WMO codes: KAUR observations XML (wmocode element), sample of 2026-11-13.",
        "# CC BY 4.0, Keskkonnaagentuur.",
        "",
        "[meta]",
        'schema_version = "1.0.0"',
        f'generated_utc = "{format_utc(utc_now())}"',
        "",
    ]
    for st in stations:
        old = existing.get(st.station_id)
        lines += [
            "[[station]]",
            f'station_id = "{st.station_id}"',
            f'name = "{st.name}"',
            "verified = true",
            f"lat_deg = {st.lat_deg}",
            f"lon_deg = {st.lon_deg}",
            f"height_m_EH2000 = {st.height_m}",
        ]
        if old is not None and old.wmo_code:
            lines.append(f'wmo_code = "{old.wmo_code}"')
        lines += [
            f'location_valid_from = "{st.period_start}"',
            f'coord_source_uri = "{src}"',
            f'height_source_uri = "{src}"',
            "",
        ]
    return "\n".join(lines)


def xml_stations_path(data_root: Path) -> Path:
    """Registry of stations seen in the observations XML."""
    return data_root / "meta" / "xml_met_stations.parquet"


#: First registry version (2026-11-13) also listed groundwater sites; removed on update.
LEGACY_XML_REGISTRY = "xml_stations.parquet"


def station_targets(settings: Settings) -> pl.DataFrame:
    """All locations at which forecasts are archived, sorted by station_id.

    Verified stations from config, plus observations-XML stations that are not within
    1 km of a verified station.
    """
    rows: list[dict[str, Any]] = [
        {
            "station_id": s.station_id,
            "name": s.name,
            "lat_deg": s.lat_deg,
            "lon_deg": s.lon_deg,
            "height_m_EH2000": s.height_m_eh2000,
            "verified": True,
            "source": "kliima_api",
        }
        for s in settings.stations
        if s.verified and s.lat_deg is not None and s.lon_deg is not None
    ]
    xml_path = xml_stations_path(settings.data_root)
    if xml_path.exists():
        verified = rows.copy()
        for x in pl.read_parquet(xml_path).iter_rows(named=True):
            dup = any(
                haversine_km(v["lat_deg"], v["lon_deg"], x["lat_deg"], x["lon_deg"])
                < MATCH_RADIUS_KM
                for v in verified
            )
            if not dup:
                rows.append(
                    {
                        "station_id": x["station_id"],
                        "name": x["name"],
                        "lat_deg": x["lat_deg"],
                        "lon_deg": x["lon_deg"],
                        "height_m_EH2000": None,
                        "verified": False,
                        "source": "obs_xml",
                    }
                )
    return pl.DataFrame(rows, schema=STATION_TARGETS_SCHEMA).sort("station_id")


def sync_stations(settings: Settings, base_url: str) -> Path:
    """Regenerate ``config/stations.toml`` from the climate API; return its path."""
    stations = fetch_kliima_stations(base_url)
    existing = {s.station_id: s for s in settings.stations}
    path = settings.config_dir / "stations.toml"
    path.write_text(render_stations_toml(stations, existing, base_url), encoding="utf-8")
    LOG.info("wrote %d stations to %s", len(stations), path)
    return path
